-- ============================================================================
-- Seed: CTFDL + OVDL rulebooks -> league_rules (generated from the league PDFs)
-- ============================================================================
-- Requires create-league-rules.sql first. Idempotent: replaces only rows with
-- source = 'pdf-seed' for these two leagues; admin-edited rows are untouched.
-- Review categorization on /rules after loading; edit anything via /admin/rules.
-- ============================================================================

DELETE FROM league_rules WHERE league_slug IN ('ctfdl','ovdl') AND source = 'pdf-seed';

